                                alignItems: "center",
                                justifyContent: "center",
                                gap: 6,
                                border: "1px solid #fda4af",
                                borderRadius: 8,
                                background: "#fff8f8",
                                color: "#ef4444",
                                fontSize: 11,
                                fontWeight: 800,
                                cursor: "pointer",
